<?xml version="1.0" encoding="utf-8"?>
<RelativeLayout xmlns:android="http://schemas.android.com/apk/res/android"
 xmlns:app="http://schemas.android.com/apk/res-auto"
 android:layout_width="match_parent"
 android:layout_height="match_parent"
 android:background="@drawable/splash_gradient_background">

 <!-- Logo Container -->
 <LinearLayout
 android:layout_width="wrap_content"
 android:layout_height="wrap_content"
 android:layout_centerInParent="true"
 android:orientation="vertical"
 android:gravity="center">

 <!-- Logo Image -->
 <ImageView
 android:id="@+id/logo_image"
 android:layout_width="120dp"
 android:layout_height="120dp"
 android:src="@drawable/kwaaiman_logo"
 android:layout_marginBottom="24dp"
 android:scaleX="0"
 android:scaleY="0" />

 <!-- App Name -->
 <TextView
 android:id="@+id/app_name"
 android:layout_width="wrap_content"
 android:layout_height="wrap_content"
 android:text="Kwaaiman"
 android:textSize="32sp"
 android:textColor="@color/white"
 android:fontFamily="sans-serif-black"
 android:letterSpacing="0.1"
 android:visibility="invisible"
 android:alpha="0"
 android:layout_marginBottom="8dp" />

 <!-- Tagline -->
 <TextView
 android:id="@+id/tagline"
 android:layout_width="wrap_content"
 android:layout_height="wrap_content"
 android:text="Student Transport Made Easy"
 android:textSize="16sp"
 android:textColor="@color/splash_tagline_color"
 android:fontFamily="sans-serif-light"
 android:visibility="invisible"
 android:alpha="0"
 android:translationY="100dp" />

 </LinearLayout>

 <!-- Loading Progress -->
 <ProgressBar
 android:id="@+id/loading_progress"
 android:layout_width="wrap_content"
 android:layout_height="wrap_content"
 android:layout_alignParentBottom="true"
 android:layout_centerHorizontal="true"
 android:layout_marginBottom="80dp"
 android:indeterminateTint="@color/white"
 android:visibility="invisible"
 android:alpha="0" />

 <!-- Version Info -->
 <TextView
 android:layout_width="wrap_content"
 android:layout_height="wrap_content"
 android:layout_alignParentBottom="true"
 android:layout_centerHorizontal="true"
 android:layout_marginBottom="32dp"
 android:text="v1.0.0"
 android:textSize="12sp"
 android:textColor="@color/splash_version_color"
 android:fontFamily="sans-serif-light" />

 <!-- Bottom Decoration -->
 <View
 android:layout_width="match_parent"
 android:layout_height="4dp"
 android:layout_alignParentBottom="true"
 android:background="@drawable/splash_bottom_decoration" />

</RelativeLayout>
```
