package com.example.kwaaimancarservices;

import android.Manifest;
import android.content.Intent;
import android.content.pm.PackageManager;
import android.location.Location;
import android.os.Bundle;
import android.view.MenuItem;
import android.view.View;
import android.widget.Button;
import android.widget.TextView;
import android.widget.Toast;

import androidx.annotation.NonNull;
import androidx.appcompat.app.ActionBarDrawerToggle;
import androidx.appcompat.app.AppCompatActivity;
import androidx.cardview.widget.CardView;
import androidx.core.app.ActivityCompat;
import androidx.core.content.ContextCompat;
import androidx.core.view.GravityCompat;
import androidx.drawerlayout.widget.DrawerLayout;

import com.example.kwaaimancarservices.databinding.ActivityMainBinding;
import com.google.android.material.bottomsheet.BottomSheetBehavior;
import com.google.android.material.card.MaterialCardView;
import com.google.android.material.floatingactionbutton.FloatingActionButton;
import com.google.android.material.navigation.NavigationView;
import com.google.android.material.textfield.TextInputEditText;

public class MainActivity extends AppCompatActivity implements NavigationView.OnNavigationItemSelectedListener {

 private ActivityMainBinding binding;
 private DrawerLayout drawerLayout;
 private NavigationView navigationView;
 private ActionBarDrawerToggle toggle;

 // Bottom Sheet Components
 private BottomSheetBehavior<View> bottomSheetBehavior;
 private MaterialCardView toCampusCard, fromCampusCard, scheduleCard;
 private TextInputEditText pickupLocationInput, destinationInput;
 private CardView tripInfoCard;
 private TextView estimatedTime, estimatedDistance, estimatedFare;
 private Button bookRideButton;

 // Map and Location Components
 private FloatingActionButton fabCurrentLocation, fabEmergency;
 private CardView tripStatusCard;
 private TextView driverName, tripStatus, estimatedArrival;

 // Permission Constants
 private static final int LOCATION_PERMISSION_REQUEST = 1001;

 @Override
 protected void onCreate(Bundle savedInstanceState) {
 super.onCreate(savedInstanceState);

 binding = ActivityMainBinding.inflate(getLayoutInflater());
 setContentView(binding.getRoot());

 initViews();
 setupToolbar();
 setupNavigationDrawer();
 setupBottomSheet();
 setupLocationServices();
 setupClickListeners();
 checkLocationPermissions();
 }

 private void initViews() {
 drawerLayout = binding.drawerLayout;
 navigationView = binding.navigationView;

 // Bottom Sheet Components
 View bottomSheet = findViewById(R.id.bottom_sheet_ride_booking);
 bottomSheetBehavior = BottomSheetBehavior.from(bottomSheet);

 toCampusCard = findViewById(R.id.to_campus_card);
 fromCampusCard = findViewById(R.id.from_campus_card);
 scheduleCard = findViewById(R.id.schedule_card);

 pickupLocationInput = findViewById(R.id.pickup_location_input);
 destinationInput = findViewById(R.id.destination_input);

 tripInfoCard = findViewById(R.id.trip_info_card);
 estimatedTime = findViewById(R.id.estimated_time);
 estimatedDistance = findViewById(R.id.estimated_distance);
 estimatedFare = findViewById(R.id.estimated_fare);

 bookRideButton = findViewById(R.id.book_ride_button);

 // FABs and Status Card
 fabCurrentLocation = binding.fabCurrentLocation;
 fabEmergency = binding.fabEmergency;
 tripStatusCard = binding.tripStatusCard;
 driverName = binding.driverName;
 tripStatus = binding.tripStatus;
 estimatedArrival = binding.estimatedArrival;
 }

 private void setupToolbar() {
 setSupportActionBar(binding.toolbar);
 if (getSupportActionBar() != null) {
 getSupportActionBar().setTitle("Kwaaiman");
 getSupportActionBar().setDisplayHomeAsUpEnabled(true);
 }
 }

 private void setupNavigationDrawer() {
 toggle = new ActionBarDrawerToggle(
 this, drawerLayout, binding.toolbar,
 R.string.navigation_drawer_open, R.string.navigation_drawer_close
 );
 drawerLayout.addDrawerListener(toggle);
 toggle.syncState();

 navigationView.setNavigationItemSelectedListener(this);
 }

 private void setupBottomSheet() {
 bottomSheetBehavior.setPeekHeight(280);
 bottomSheetBehavior.setHideable(false);
 bottomSheetBehavior.setState(BottomSheetBehavior.STATE_COLLAPSED);

 bottomSheetBehavior.addBottomSheetCallback(new BottomSheetBehavior.BottomSheetCallback() {
 @Override
 public void onStateChanged(@NonNull View bottomSheet, int newState) {
 // Handle bottom sheet state changes
 }

 @Override
 public void onSlide(@NonNull View bottomSheet, float slideOffset) {
 // Handle bottom sheet sliding
 }
 });
 }

 private void setupLocationServices() {
 // Initialize Google Maps and location services
 // This would typically involve initializing the map fragment
 }

 private void setupClickListeners() {
 // Quick Action Cards
 toCampusCard.setOnClickListener(v -> handleToCampusClick());
 fromCampusCard.setOnClickListener(v -> handleFromCampusClick());
 scheduleCard.setOnClickListener(v -> handleScheduleClick());

 // Book Ride Button
 bookRideButton.setOnClickListener(v -> handleBookRideClick());

 // FABs
 fabCurrentLocation.setOnClickListener(v -> getCurrentLocation());
 fabEmergency.setOnClickListener(v -> handleEmergencyClick());

 // Location Input Focus Listeners
 pickupLocationInput.setOnFocusChangeListener((v, hasFocus) -> {
 if (hasFocus) {
 // Open location picker activity or places autocomplete
 }
 });

 destinationInput.setOnFocusChangeListener((v, hasFocus) -> {
 if (hasFocus) {
 // Open location picker activity or places autocomplete
 }
 });
 }

 private void handleToCampusClick() {
 // Set destination to campus coordinates
 destinationInput.setText("University of Northern Cape - Kimberley Campus");
 updateTripEstimates();
 showTripInfo(true);
 bookRideButton.setText("Book Ride to Campus");
 }

 private void handleFromCampusClick() {
 // Set pickup location to campus
 pickupLocationInput.setText("University of Northern Cape - Kimberley Campus");
 updateTripEstimates();
 showTripInfo(true);
 bookRideButton.setText("Book Ride from Campus");
 }

 private void handleScheduleClick() {
 // Open schedule ride activity or dialog
 Toast.makeText(this, "Schedule Ride - Coming Soon!", Toast.LENGTH_SHORT).show();
 }

 private void handleBookRideClick() {
 String pickup = pickupLocationInput.getText().toString().trim();
 String destination = destinationInput.getText().toString().trim();

 if (pickup.isEmpty()) {
 pickupLocationInput.setError("Please enter pickup location");
 return;
 }

 if (destination.isEmpty()) {
 destinationInput.setError("Please enter destination");
 return;
 }

 // Simulate ride booking
 bookRideButton.setEnabled(false);
 bookRideButton.setText("Finding Driver...");

 // Simulate finding driver delay
 bookRideButton.postDelayed(() -> {
 simulateDriverFound();
 }, 3000);
 }

 private void simulateDriverFound() {
 // Show trip status card
 tripStatusCard.setVisibility(View.VISIBLE);
 driverName.setText("Thabo M.");
 tripStatus.setText("Driver assigned");
 estimatedArrival.setText("Arrives in 3 min");

 // Hide bottom sheet
 bottomSheetBehavior.setState(BottomSheetBehavior.STATE_COLLAPSED);

 // Reset book button
 bookRideButton.setEnabled(true);
 bookRideButton.setText("Find Kwaaiman");

 Toast.makeText(this, "Driver found! Thabo is on the way", Toast.LENGTH_LONG).show();
 }

 private void getCurrentLocation() {
 if (ContextCompat.checkSelfPermission(this, Manifest.permission.ACCESS_FINE_LOCATION)
 == PackageManager.PERMISSION_GRANTED) {
 // Get current location and update map
 Toast.makeText(this, "Getting your location...", Toast.LENGTH_SHORT).show();
 } else {
 checkLocationPermissions();
 }
 }

 private void handleEmergencyClick() {
 // Handle emergency button click
 Toast.makeText(this, "Emergency services contacted!", Toast.LENGTH_LONG).show();
 // In a real app, this would contact emergency services or designated contacts
 }

 private void updateTripEstimates() {
 // Calculate estimated time, distance, and fare
 // This would typically involve calling Google Maps API
 estimatedTime.setText("8 min");
 estimatedDistance.setText("2.3 km");
 estimatedFare.setText("R 25");
 }

 private void showTripInfo(boolean show) {
 tripInfoCard.setVisibility(show ? View.VISIBLE : View.GONE);
 }

 private void checkLocationPermissions() {
 if (ContextCompat.checkSelfPermission(this, Manifest.permission.ACCESS_FINE_LOCATION)
 != PackageManager.PERMISSION_GRANTED) {

 ActivityCompat.requestPermissions(this,
 new String[]{Manifest.permission.ACCESS_FINE_LOCATION},
 LOCATION_PERMISSION_REQUEST);
 }
 }

 @Override
 public void onRequestPermissionsResult(int requestCode, @NonNull String[] permissions,
 @NonNull int[] grantResults) {
 super.onRequestPermissionsResult(requestCode, permissions, grantResults);

 if (requestCode == LOCATION_PERMISSION_REQUEST) {
 if (grantResults.length > 0 && grantResults[0] == PackageManager.PERMISSION_GRANTED) {
 // Permission granted, initialize location services
 setupLocationServices();
 } else {
 Toast.makeText(this, "Location permission is required for the app to work properly",
 Toast.LENGTH_LONG).show();
 }
 }
 }

 @Override
 public boolean onNavigationItemSelected(@NonNull MenuItem item) {
 int id = item.getItemId();

 // Handle navigation menu item clicks
 switch (id) {
 case R.id.nav_profile:
 // Open profile activity
 break;
 case R.id.nav_trip_history:
 // Open trip history activity
 break;
 case R.id.nav_payment:
 // Open payment methods activity
 break;
 case R.id.nav_settings:
 // Open settings activity
 break;
 case R.id.nav_support:
 // Open support activity
 break;
 case R.id.nav_logout:
 // Handle logout
 handleLogout();
 break;
 }

 drawerLayout.closeDrawer(GravityCompat.START);
 return true;
 }

 private void handleLogout() {
 // Clear user session and navigate to auth activity
 getSharedPreferences("KwaaimanPrefs", MODE_PRIVATE)
 .edit()
 .putBoolean("is_logged_in", false)
 .apply();

 // Navigate to auth activity
 Intent intent = new Intent(this, com.example.kwaaimancarservices.activities.AuthActivity.class);
 startActivity(intent);
 finish();
 }

 @Override
 public void onBackPressed() {
 if (drawerLayout.isDrawerOpen(GravityCompat.START)) {
 drawerLayout.closeDrawer(GravityCompat.START);
 } else if (bottomSheetBehavior.getState() == BottomSheetBehavior.STATE_EXPANDED) {
 bottomSheetBehavior.setState(BottomSheetBehavior.STATE_COLLAPSED);
 } else {
 super.onBackPressed();
 }
 }
}
