+package com.example.kwaaimancarservices.activities;

+import android.content.Intent;
+import android.os.Bundle;
+import android.view.MenuItem;
+import android.view.View;
+import android.widget.Button;
+import android.widget.LinearLayout;
+import android.widget.TextView;
+import android.widget.Toast;
+
+import androidx.appcompat.app.AppCompatActivity;
+import androidx.recyclerview.widget.LinearLayoutManager;
+import androidx.recyclerview.widget.RecyclerView;
+
+import com.example.kwaaimancarservices.R;
+import com.example.kwaaimancarservices.adapters.VehicleTypeAdapter;
+import com.example.kwaaimancarservices.models.VehicleType;
+import com.google.android.material.card.MaterialCardView;
+
+import java.util.ArrayList;
+import java.util.List;
+
+public class RideBookingActivity extends AppCompatActivity implements VehicleTypeAdapter.OnVehicleTypeClickListener {
+
+ private TextView pickupLocationText, destinationText, estimatedFareText, estimatedTimeText;
+ private RecyclerView vehicleTypesRecyclerView;
+ private VehicleTypeAdapter vehicleAdapter;
+ private Button bookRideButton;
+ private LinearLayout paymentMethodContainer;
+ private MaterialCardView selectedPaymentCard;
+
+ private String pickupLocation, destinationLocation;
+ private VehicleType selectedVehicleType;
+ private boolean isScheduled = false;
+
+ @Override
+ protected void onCreate(Bundle savedInstanceState) {
+ super.onCreate(savedInstanceState);
+ setContentView(R.layout.activity_ride_booking);
+
+ getIntentData();
+ initViews();
+ setupToolbar();
+ setupRecyclerView();
+ setupClickListeners();
+ loadVehicleTypes();
+ updateLocationDisplay();
+ }
+
+ private void getIntentData() {
+ Intent intent = getIntent();
+ pickupLocation = intent.getStringExtra("pickup_location");
+ destinationLocation = intent.getStringExtra("destination_location");
+ isScheduled = "scheduled".equals(intent.getStringExtra("ride_type"));
+ }
+
+ private void initViews() {
+ pickupLocationText = findViewById(R.id.pickup_location_text);
+ destinationText = findViewById(R.id.destination_text);
+ estimatedFareText = findViewById(R.id.estimated_fare_text);
+ estimatedTimeText = findViewById(R.id.estimated_time_text);
+ vehicleTypesRecyclerView = findViewById(R.id.vehicle_types_recycler_view);
+ bookRideButton = findViewById(R.id.book_ride_button);
+ paymentMethodContainer = findViewById(R.id.payment_method_container);
+ selectedPaymentCard = findViewById(R.id.selected_payment_card);
+ }
+
+ private void setupToolbar() {
+ if (getSupportActionBar() != null) {
+ getSupportActionBar().setDisplayHomeAsUpEnabled(true);
+ getSupportActionBar().setTitle(isScheduled ? "Schedule Ride" : "Book Ride");
+ }
+ }
+
+ private void setupRecyclerView() {
+ vehicleAdapter = new VehicleTypeAdapter(this, this);
+ vehicleTypesRecyclerView.setLayoutManager(new LinearLayoutManager(this));
+ vehicleTypesRecyclerView.setAdapter(vehicleAdapter);
+ }
+
+ private void setupClickListeners() {
+ bookRideButton.setOnClickListener(v -> handleBookRide());
+
+ selectedPaymentCard.setOnClickListener(v -> {
+ Intent intent = new Intent(this, PaymentMethodsActivity.class);
+ startActivityForResult(intent, 200);
+ });
+ }
+
+ private void loadVehicleTypes() {
+ List<VehicleType> vehicleTypes = new ArrayList<>();
+
+ // Standard vehicle types like Uber/Bolt
+ vehicleTypes.add(new VehicleType("Economy", "Affordable rides",
+ "R 35-45", "2-5 min", R.drawable.ic_car_economy, true));
+ vehicleTypes.add(new VehicleType("Comfort", "More space and comfort",
+ "R 45-60", "3-7 min", R.drawable.ic_car_comfort, true));
+ vehicleTypes.add(new VehicleType("Premium", "High-end vehicles",
+ "R 65-85", "5-10 min", R.drawable.ic_car_premium, true));
+ vehicleTypes.add(new VehicleType("XL", "6+ seats for groups",
+ "R 55-75", "4-8 min", R.drawable.ic_car_xl, true));
+
+ if (!isScheduled) {
+ vehicleTypes.add(new VehicleType("Moto", "Motorcycle rides",
+ "R 20-30", "1-3 min", R.drawable.ic_motorcycle, true));
+ }
+
+ vehicleAdapter.updateVehicleTypes(vehicleTypes);
+
+ // Select first item by default
+ if (!vehicleTypes.isEmpty()) {
+ selectedVehicleType = vehicleTypes.get(0);
+ updatePriceDisplay();
+ }
+ }
+
+ private void updateLocationDisplay() {
+ if (pickupLocation != null) {
+ pickupLocationText.setText(pickupLocation);
+ }
+ if (destinationLocation != null) {
+ destinationText.setText(destinationLocation);
+ }
+ }
+
+ private void updatePriceDisplay() {
+ if (selectedVehicleType != null) {
+ estimatedFareText.setText(selectedVehicleType.getPriceRange());
+ estimatedTimeText.setText(selectedVehicleType.getEta());
+ }
+ }
+
+ @Override
+ public void onVehicleTypeClick(VehicleType vehicleType) {
+ selectedVehicleType = vehicleType;
+ updatePriceDisplay();
+ }
+
+ private void handleBookRide() {
+ if (selectedVehicleType == null) {
+ Toast.makeText(this, "Please select a vehicle type", Toast.LENGTH_SHORT).show();
+ return;
+ }
+
+ if (pickupLocation == null || destinationLocation == null) {
+ Toast.makeText(this, "Please set pickup and destination", Toast.LENGTH_SHORT).show();
+ return;
+ }
+
+ // Show booking confirmation and navigate to trip tracking
+ bookRideButton.setEnabled(false);
+ bookRideButton.setText("Finding Driver...");
+
+ // Simulate finding driver
+ bookRideButton.postDelayed(() -> {
+ Intent intent = new Intent(this, TripTrackingActivity.class);
+ intent.putExtra("pickup_location", pickupLocation);
+ intent.putExtra("destination_location", destinationLocation);
+ intent.putExtra("vehicle_type", selectedVehicleType.getName());
+ intent.putExtra("estimated_fare", selectedVehicleType.getPriceRange());
+ startActivity(intent);
+ finish();
+ }, 2000);
+ }
+
+ @Override
+ protected void onActivityResult(int requestCode, int resultCode, Intent data) {
+ super.onActivityResult(requestCode, resultCode, data);
+
+ if (requestCode == 200 && resultCode == RESULT_OK) {
+ // Payment method selected
+ String paymentMethod = data.getStringExtra("selected_payment_method");
+ // Update UI to show selected payment method
+ Toast.makeText(this, "Payment method: " + paymentMethod, Toast.LENGTH_SHORT).show();
+ }
+ }
+
+ @Override
+ public boolean onOptionsItemSelected(MenuItem item) {
+ if (item.getItemId() == android.R.id.home) {
+ finish();
+ return true;
+ }
+ return super.onOptionsItemSelected(item);
+ }
+}
