ndle trip cancellation\n showCancelTripDialog();\n });\n }\n\n private void updateLocationDisplay() {\n if (pickupLocation != null) {\n pickupLocationText.setText(pickupLocation);\n }\n if (destinationLocation != null) {\n destinationText.setText(destinationLocation);\n }\n if (estimatedFare != null) {\n fareEstimateText.setText(estimatedFare);\n }\n if (vehicleType != null) {\n vehicleInfoText.setText(vehicleType + \" • White Toyota Corolla • ABC 123 GP\");\n }\n }\n\n private void startTripSimulation() {\n updateTripStatus();\n }\n\n private void updateTripStatus() {\n if (tripProgressStep < TRIP_STATUS.length) {\n tripStatusText.setText(TRIP_STATUS[tripProgressStep]);\n \n switch (tripProgressStep) {\n case 0: // Finding driver\n etaText.setText(\"Searching...\");\n driverInfoCard.setVisibility(View.GONE);\n break;\n case 1: // Driver assigned\n showDriverInfo();\n etaText.setText(\"Arriving in 3 min\");\n break;\n case 2: // Driver arriving\n etaText.setText(\"Arriving in 2 min\");\n break;\n case 3: // Driver arrived\n etaText.setText(\"Driver has arrived\");\n cancelTripButton.setText(\"Cancel\");\n break;\n case 4: // Trip in progress\n etaText.setText(\"15 min to destination\");\n cancelTripButton.setVisibility(View.GONE);\n break;\n case 5: // Trip completed\n showTripCompleted();\n return;\n }\n \n tripProgressStep++;\n \n // Schedule next update (simulate real-time updates)\n updateHandler.postDelayed(this::updateTripStatus, \n tripProgressStep == 1 ? 3000 : 5000); // 3s for first update, 5s for others\n }\n }\n\n private void showDriverInfo() {\n driverInfoCard.setVisibility(View.VISIBLE);\n driverNameText.setText(\"Thabo Mthembu\");\n driverPhotoView.setImageResource(R.drawable.default_driver_image);\n \n // Rating could be shown here\n // driverRatingText.setText(\"4.9\");\n }\n\n private void showTripCompleted() {\n tripStatusText.setText(\"Trip completed!\");\n etaText.setText(\"You have arrived\");\n tripActionsLayout.setVisibility(View.GONE);\n \n 