+import android.view.MenuItem;
+import android.view.View;
+import android.widget.Button;
+import android.widget.ImageView;
+import android.widget.LinearLayout;
+import android.widget.TextView;
+import android.widget.Toast;
+
+import androidx.appcompat.app.AppCompatActivity;
+import androidx.cardview.widget.CardView;
+
+import com.example.kwaaimancarservices.R;
+
+public class TripTrackingActivity extends AppCompatActivity {
+
+ private TextView tripStatusText, driverNameText, vehicleInfoText, etaText;
+ private TextView pickupLocationText, destinationText, fareEstimateText;
+ private ImageView driverPhotoView;
+ private Button callDriverButton, messageDriverButton, cancelTripButton;
+ private CardView driverInfoCard, tripProgressCard;
+ private LinearLayout tripActionsLayout;
+
+ private String pickupLocation, destinationLocation, vehicleType, estimatedFare;
+ private Handler updateHandler = new Handler();
+ private int tripProgressStep = 0;
+
+ // Trip status steps
+ private static final String[] TRIP_STATUS = {
+ "Finding driver...",
+ "Driver assigned",
+ "Driver arriving",
+ "Driver arrived",
+ "Trip in progress",
+ "Trip completed"
+ };
+
+ @Override
+ protected void onCreate(Bundle savedInstanceState) {
+ super.onCreate(savedInstanceState);
+ setContentView(R.layout.activity_trip_tracking);
+
+ getIntentData();
+ initViews();
+ setupToolbar();
+ setupClickListeners();
+ startTripSimulation();
+ }
+
+ private void getIntentData() {
+ Intent intent = getIntent();
+ pickupLocation = intent.getStringExtra("pickup_location");
+ destinationLocation = intent.getStringExtra("destination_location");
+ vehicleType = intent.getStringExtra("vehicle_type");
+ estimatedFare = intent.getStringExtra("estimated_fare");
+ }
+
+ private void initViews() {
+ tripStatusText = findViewById(R.id.trip_status_text);
+ driverNameText = findViewById(R.id.driver_name_text);
+ vehicleInfoText = findViewById(R.id.vehicle_info_text);
+ etaText = findViewById(R.id.eta_text);
+ pickupLocationText = findViewById(R.id.pickup_location_text);
+ destinationText = findViewById(R.id.destination_text);
+ fareEstimateText = findViewById(R.id.fare_estimate_text);
+ driverPhotoView = findViewById(R.id.driver_photo_view);
+ callDriverButton = findViewById(R.id.call_driver_button);
+ messageDriverButton = findViewById(R.id.message_driver_button);
+ cancelTripButton = findViewById(R.id.cancel_trip_button);
+ driverInfoCard = findViewById(R.id.driver_info_card);
+ tripProgressCard = findViewById(R.id.trip_progress_card);
+ tripActionsLayout = findViewById(R.id.trip_actions_layout);
+
+ updateLocationDisplay();
+ }
+
+ private void setupToolbar() {
+ if (getSupportActionBar() != null) {
+ getSupportActionBar().setDisplayHomeAsUpEnabled(true);
+ getSupportActionBar().setTitle("Your Trip");
+ }
+ }
+
+ private void setupClickListeners() {
+ callDriverButton.setOnClickListener(v -> {
+ // Simulate calling driver
+ Toast.makeText(this, "Calling driver...", Toast.LENGTH_SHORT).show();
+ });
+
+ messageDriverButton.setOnClickListener(v -> {
+ // Open messaging with driver
+ Toast.makeText(this, "Opening chat with driver...", Toast.LENGTH_SHORT).show();
+ });
+
+ cancelTripButton.setOnClickListener(v -> {
+ // Handle trip cancellation
+ showCancelTripDialog();
+ });
+ }
+
+ private void updateLocationDisplay() {
+ if (pickupLocation != null) {
+ pickupLocationText.setText(pickupLocation);
+ }
+ if (destinationLocation != null) {
+ destinationText.setText(destinationLocation);
+ }
+ if (estimatedFare != null) {
+ fareEstimateText.setText(estimatedFare);
+ }
+ if (vehicleType != null) {
+ vehicleInfoText.setText(vehicleType + " • White Toyota Corolla • ABC 123 GP");
+ }
+ }
+
+ private void startTripSimulation() {
+ updateTripStatus();
+ }
+
+ private void updateTripStatus() {
+ if (tripProgressStep < TRIP_STATUS.length) {
+ tripStatusText.setText(TRIP_STATUS[tripProgressStep]);
+
+ switch (tripProgressStep) {
+ case 0: // Finding driver
+ etaText.setText("Searching...");
+ driverInfoCard.setVisibility(View.GONE);
+ break;
+ case 1: // Driver assigned
+ showDriverInfo();
+ etaText.setText("Arriving in 3 min");
+ break;
+ case 2: // Driver arriving
+ etaText.setText("Arriving in 2 min");
+ break;
+ case 3: // Driver arrived
+ etaText.setText("Driver has arrived");
+ cancelTripButton.setText("Cancel");
+ break;
+ case 4: // Trip in progress
+ etaText.setText("15 min to destination");
+ cancelTripButton.setVisibility(View.GONE);
+ break;
+ case 5: // Trip completed
+ showTripCompleted();
+ return;
+ }
+
+ tripProgressStep++;
+
+ // Schedule next update (simulate real-time updates)
+ updateHandler.postDelayed(this::updateTripStatus,
+ tripProgressStep == 1 ? 3000 : 5000); // 3s for first update, 5s for others
+ }
+ }
+
+ private void showDriverInfo() {
+ driverInfoCard.setVisibility(View.VISIBLE);
+ driverNameText.setText("Thabo Mthembu");
+ driverPhotoView.setImageResource(R.drawable.default_driver_image);
+
+ // Rating could be shown here
+ // driverRatingText.setText("4.9");
+ }
+
+ private void showTripCompleted() {
+ tripStatusText.setText("Trip completed!");
+ etaText.setText("You have arrived");
+ tripActionsLayout.setVisibility(View.GONE);
+
+ // Navigate to trip completion/rating activity
+ updateHandler.postDelayed(() -> {
+ Toast.makeText(this, "Rate your trip!", Toast.LENGTH_LONG).show();
+ finish();
+ }, 2000);
+ }
+
+ private void showCancelTripDialog() {
+ // In a real app, show a proper dialog
+ Toast.makeText(this, "Trip cancelled", Toast.LENGTH_SHORT).show();
+ finish();
+ }
+
+ @Override
+ protected void onDestroy() {
+ super.onDestroy();
+ if (updateHandler != null) {
+ updateHandler.removeCallbacksAndMessages(null);
+ }
+ }
+
+ @Override
+ public boolean onOptionsItemSelected(MenuItem item) {
+ if (item.getItemId() == android.R.id.home) {
+ // Show confirmation dialog before going back during active trip
+ if (tripProgressStep >= 2 && tripProgressStep < 5) {
+ Toast.makeText(this, "Trip is in progress", Toast.LENGTH_SHORT).show();
+ return true;
+ }
+ finish();
+ return true;
+ }
+ return super.onOptionsItemSelected(item);
+ }
+}
