+package com.example.kwaaimancarservices.activities;

+import android.content.Intent;
+import android.net.Uri;
+import android.os.Bundle;
+import android.view.MenuItem;
+import android.widget.Toast;
+
+import androidx.appcompat.app.AppCompatActivity;
+import androidx.cardview.widget.CardView;
+
+import com.example.kwaaimancarservices.R;
+
+public class SupportActivity extends AppCompatActivity {
+
+ private CardView emergencyCard, callSupportCard, chatSupportCard, faqCard;
+ private boolean isEmergencyMode = false;
+
+ @Override
+ protected void onCreate(Bundle savedInstanceState) {
+ super.onCreate(savedInstanceState);
+ setContentView(R.layout.activity_support);
+
+ isEmergencyMode = getIntent().getBooleanExtra("emergency_mode", false);
+
+ initViews();
+ setupToolbar();
+ setupClickListeners();
+ }
+
+ private void initViews() {
+ emergencyCard = findViewById(R.id.emergency_card);
+ callSupportCard = findViewById(R.id.call_support_card);
+ chatSupportCard = findViewById(R.id.chat_support_card);
+ faqCard = findViewById(R.id.faq_card);
+ }
+
+ private void setupToolbar() {
+ if (getSupportActionBar() != null) {
+ getSupportActionBar().setDisplayHomeAsUpEnabled(true);
+ getSupportActionBar().setTitle(isEmergencyMode ? "Emergency" : "Support");
+ }
+ }
+
+ private void setupClickListeners() {
+ emergencyCard.setOnClickListener(v -> handleEmergency());
+ callSupportCard.setOnClickListener(v -> callSupport());
+ chatSupportCard.setOnClickListener(v -> startChat());
+ faqCard.setOnClickListener(v -> openFAQ());
+ }
+
+ private void handleEmergency() {
+ // Call emergency services
+ Intent callIntent = new Intent(Intent.ACTION_CALL);
+ callIntent.setData(Uri.parse("tel:10111")); // South African emergency number
+
+ try {
+ startActivity(callIntent);
+ } catch (SecurityException e) {
+ Toast.makeText(this, "Permission required to make calls", Toast.LENGTH_SHORT).show();
+ }
+ }
+
+ private void callSupport() {
+ Intent callIntent = new Intent(Intent.ACTION_DIAL);
+ callIntent.setData(Uri.parse("tel:0800123456")); // Support number
+ startActivity(callIntent);
+ }
+
+ private void startChat() {
+ Toast.makeText(this, "Opening chat support...", Toast.LENGTH_SHORT).show();
+ // Open chat support functionality
+ }
+
+ private void openFAQ() {
+ Toast.makeText(this, "Opening FAQ...", Toast.LENGTH_SHORT).show();
+ // Open FAQ activity or web page
+ }
+
+ @Override
+ public boolean onOptionsItemSelected(MenuItem item) {
+ if (item.getItemId() == android.R.id.home) {
+ finish();
+ return true;
+ }
+ return super.onOptionsItemSelected(item);
+ }
+}
