+package com.example.kwaaimancarservices.activities;

+import android.os.Bundle;
+import android.view.MenuItem;
+import android.widget.Button;
+import android.widget.Switch;
+import android.widget.TextView;
+import android.widget.Toast;
+
+import androidx.appcompat.app.AppCompatActivity;
+import androidx.cardview.widget.CardView;
+
+import com.example.kwaaimancarservices.R;
+
+public class DriverDashboardActivity extends AppCompatActivity {
+
+ private Switch onlineStatusSwitch;
+ private TextView earningsToday, tripsCompleted, driverRating;
+ private CardView earningsCard, tripsCard, ratingsCard;
+ private Button viewTripsButton, cashOutButton;
+
+ @Override
+ protected void onCreate(Bundle savedInstanceState) {
+ super.onCreate(savedInstanceState);
+ setContentView(R.layout.activity_driver_dashboard);
+
+ initViews();
+ setupToolbar();
+ setupClickListeners();
+ loadDriverData();
+ }
+
+ private void initViews() {
+ onlineStatusSwitch = findViewById(R.id.online_status_switch);
+ earningsToday = findViewById(R.id.earnings_today);
+ tripsCompleted = findViewById(R.id.trips_completed);
+ driverRating = findViewById(R.id.driver_rating);
+ earningsCard = findViewById(R.id.earnings_card);
+ tripsCard = findViewById(R.id.trips_card);
+ ratingsCard = findViewById(R.id.ratings_card);
+ viewTripsButton = findViewById(R.id.view_trips_button);
+ cashOutButton = findViewById(R.id.cash_out_button);
+ }
+
+ private void setupToolbar() {
+ if (getSupportActionBar() != null) {
+ getSupportActionBar().setDisplayHomeAsUpEnabled(true);
+ getSupportActionBar().setTitle("Driver Dashboard");
+ }
+ }
+
+ private void setupClickListeners() {
+ onlineStatusSwitch.setOnCheckedChangeListener((buttonView, isChecked) -> {
+ if (isChecked) {
+ Toast.makeText(this, "You're now online and accepting trips", Toast.LENGTH_SHORT).show();
+ } else {
+ Toast.makeText(this, "You're now offline", Toast.LENGTH_SHORT).show();
+ }
+ });
+
+ viewTripsButton.setOnClickListener(v -> {
+ Toast.makeText(this, "Viewing trip history...", Toast.LENGTH_SHORT).show();
+ });
+
+ cashOutButton.setOnClickListener(v -> {
+ Toast.makeText(this, "Processing cash out...", Toast.LENGTH_SHORT).show();
+ });
+ }
+
+ private void loadDriverData() {
+ // Load driver statistics
+ earningsToday.setText("R 450.00");
+ tripsCompleted.setText("12");
+ driverRating.setText("4.8");
+ }
+
+ @Override
+ public boolean onOptionsItemSelected(MenuItem item) {
+ if (item.getItemId() == android.R.id.home) {
+ finish();
+ return true;
+ }
+ return super.onOptionsItemSelected(item);
+ }
+}
