+
+public class LocationTrackingService extends Service {
+
+ private static final int SERVICE_ID = 1001;
+ private static final String CHANNEL_ID = "location_tracking";
+
+ @Override
+ public void onCreate() {
+ super.onCreate();
+ createNotificationChannel();
+ }
+
